def plot_roc_curve_with_std_interactive(
    y_probs_folds,
    y_true_folds,
    n_points=200,
    show_folds=True,
    title="ROC curve with cross-validation"
):

    fpr_grid = np.linspace(0, 1, n_points)

    tprs = []
    aucs = []

    fig = go.Figure()

    # ------------------------------------------------------------
    # Per-fold ROC
    # ------------------------------------------------------------
    for i, (y_prob, y_true) in enumerate(zip(y_probs_folds, y_true_folds)):

        fpr, tpr, _ = roc_curve(y_true, y_prob)
        roc_auc = auc(fpr, tpr)

        tpr_interp = np.interp(fpr_grid, fpr, tpr)
        tpr_interp[0] = 0.0

        tprs.append(tpr_interp)
        aucs.append(roc_auc)

        if show_folds:
            fig.add_trace(go.Scatter(
                x=fpr,
                y=tpr,
                mode="lines",
                name=f"Fold {i+1} (AUC={roc_auc:.2f})",
                opacity=0.4
            ))

    tprs = np.array(tprs)

    # ------------------------------------------------------------
    # Mean + std
    # ------------------------------------------------------------
    mean_tpr = tprs.mean(axis=0)
    mean_tpr[-1] = 1.0

    std_tpr = tprs.std(axis=0)

    mean_auc = np.mean(aucs)
    std_auc = np.std(aucs)

    upper = np.minimum(mean_tpr + std_tpr, 1)
    lower = np.maximum(mean_tpr - std_tpr, 0)

    # Mean ROC
    fig.add_trace(go.Scatter(
        x=fpr_grid,
        y=mean_tpr,
        mode="lines",
        name=f"Mean ROC (AUC={mean_auc:.2f} ± {std_auc:.2f})",
        line=dict(width=3, color="red")
    ))

    # Std band
    fig.add_trace(go.Scatter(
        x=np.concatenate([fpr_grid, fpr_grid[::-1]]),
        y=np.concatenate([upper, lower[::-1]]),
        fill="toself",
        fillcolor="rgba(128,128,128,0.2)",
        line=dict(color="rgba(255,255,255,0)"),
        hoverinfo="skip",
        name="±1 std. dev."
    ))

    # Chance line
    fig.add_trace(go.Scatter(
        x=[0, 1],
        y=[0, 1],
        mode="lines",
        line=dict(dash="dash", color="gray"),
        name="Chance"
    ))

    # ------------------------------------------------------------
    # Styling: black axes + centered title
    # ------------------------------------------------------------
    fig.update_layout(
        title=dict(
            text=title,
            x=0.5,              # center title
            xanchor="center"
        ),
            xaxis=dict(
            range=[0, 1],
            autorange=False,
            title="False Positive Rate",
            showline=True,
            linecolor="black",
            mirror=True,
            ticks="outside",
            scaleanchor="y",
            scaleratio=1
        ),
        yaxis=dict(
            range=[0, 1],
            autorange=False,
            title="True Positive Rate",
            showline=True,
            linecolor="black",
            mirror=True,
            ticks="outside"
        ),
        width=700,
        height=700,
        template="plotly_white",
        legend=dict(orientation="v")
    )

    fig.show()

    return fig

